BEGIN;
create temp table assertion_count(n int);insert into assertion_count values(0);
create function pg_temp.check_it(v boolean,label text)returns void language plpgsql as $$begin if v is distinct from true then raise exception 'Assertion failed: %',label;end if;update assertion_count set n=n+1;end$$;
create function pg_temp.throws(statement text,label text)returns void language plpgsql as $$declare failed boolean:=false;begin begin execute statement;exception when others then failed:=true;end;perform pg_temp.check_it(failed,label);end$$;
create temp table st(k text primary key,v jsonb);
insert into public.organizations(id,name)values('ee620000-0000-4000-8000-000000000001','Team access SQL fixture'),('ee620000-0000-4000-8000-000000000002','Other team access SQL fixture');
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at,raw_user_meta_data)select ('ee620000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','team-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp(),'{"full_name":"Team fixture member","private":"PRIVATE-AUTH-FIXTURE"}'from generate_series(101,107)n;
insert into public.profiles(id,org_id,role,full_name)select ('ee620000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,case when n<=103 then'ee620000-0000-4000-8000-000000000001'::uuid when n=105 then'ee620000-0000-4000-8000-000000000002'::uuid end,case when n=101 then'admin'else'viewer'end,'Team fixture member '||n from generate_series(101,107)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role,full_name=excluded.full_name;
create function pg_temp.read_team(b jsonb default'{}',a uuid default'ee620000-0000-4000-8000-000000000101')returns jsonb language sql as $$select public.read_team_access(a,'ee620000-0000-4000-8000-000000000001',b)$$;
create function pg_temp.decide(i uuid,b jsonb,a uuid default'ee620000-0000-4000-8000-000000000101',token text default null)returns jsonb language sql as $$select public.decide_team_access(i,'ee620000-0000-4000-8000-000000000001',a,b,token)$$;
create function pg_temp.role_input(target uuid,role text default'manager',operation text default'change_role')returns jsonb language sql as $$select jsonb_build_object('operation',operation,'memberId',target,'memberHash',public.knowledge_hash(public.team_member_view(target)),'rosterHash',public.knowledge_hash(public.team_roster('ee620000-0000-4000-8000-000000000001')),'confirmed',true,'reason','Review this exact team membership')||case when operation='change_role'then jsonb_build_object('role',role)else'{}'end$$;
create function pg_temp.invite_input(email text default'team-104@fixture.invalid',role text default'manager')returns jsonb language sql as $$select jsonb_build_object('operation','create_invitation','email',email,'role',role,'expiresInDays',7,'confirmed',true,'reason','Invite the exact reviewed team member')$$;
create function pg_temp.invite_control(i uuid,op text default'rotate_invitation')returns jsonb language sql as $$select jsonb_build_object('operation',op,'invitationId',i,'invitationHash',public.team_invitation_hash(t),'confirmed',true,'reason','Review this exact saved invitation')||case when op='rotate_invitation'then'{"expiresInDays":7}'::jsonb else'{}'end from public.team_invitations t where id=i$$;
create function pg_temp.join_input(a uuid,token text,op text default'accept')returns jsonb language sql as $$select jsonb_build_object('operation',op,'invitationHash',public.team_join_context(a,token)->>'invitationHash','confirmed',true,'reason','Review and confirm the exact invitation')$$;
select pg_temp.check_it(pg_temp.read_team()->>'total'='3','native roster includes only organization members');
select pg_temp.check_it(pg_temp.read_team()::text not like'%PRIVATE-AUTH-FIXTURE%','directory excludes private auth metadata');
select pg_temp.check_it(pg_temp.read_team('{}','ee620000-0000-4000-8000-000000000105')->>'state'='forbidden','cross-organization directory held');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000201',pg_temp.role_input('ee620000-0000-4000-8000-000000000101','viewer'))->>'state'='last_admin','last available admin cannot be demoted');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000201',pg_temp.role_input('ee620000-0000-4000-8000-000000000101',null,'remove_member'))->>'state'='self_removal','self removal held');
insert into st values('roleInput',pg_temp.role_input('ee620000-0000-4000-8000-000000000103'));
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000202',(select v from st where k='roleInput'))->>'state'='saved','role change saves with evidence');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000202',(select v from st where k='roleInput'))->>'state'='replayed','lost role response recovers one decision');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000202',pg_temp.role_input('ee620000-0000-4000-8000-000000000103','admin'))->>'state'='request_conflict','changed body cannot reuse role request');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000203',(select v from st where k='roleInput'))->>'state'='team_changed','stale exact roster review held');
select pg_temp.check_it((select role='manager'from public.profiles where id='ee620000-0000-4000-8000-000000000103')and exists(select 1 from public.shared_action_events where id='ee620000-0000-4000-8000-000000000202'and property_id is null and product='team'and action='team.role_changed'),'role and organization-scoped event commit together');
select pg_temp.throws($q$update public.profiles set role='viewer'where id='ee620000-0000-4000-8000-000000000103'$q$,'raw adopted role update held');
select pg_temp.throws($q$delete from public.shared_action_events where id='ee620000-0000-4000-8000-000000000202'$q$,'organization action remains immutable with null property');
select pg_temp.throws($q$delete from public.team_decisions where id='ee620000-0000-4000-8000-000000000202'$q$,'private decision remains immutable');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000204',pg_temp.role_input('ee620000-0000-4000-8000-000000000102','admin'))->>'state'='saved','another reviewed admin can be appointed');
insert into st values('selfDemotion',pg_temp.role_input('ee620000-0000-4000-8000-000000000101','viewer'));
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000205',(select v from st where k='selfDemotion'))->>'state'='saved','self demotion preserves another available admin');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000205',(select v from st where k='selfDemotion'))->>'state'='replayed','self-demoted actor can recover the exact successful decision');
select pg_temp.check_it(pg_temp.read_team('{"kind":"decision","decisionId":"ee620000-0000-4000-8000-000000000205"}')->>'state'='ready','self demotion receipt remains recoverable');
select pg_temp.check_it(pg_temp.read_team('{"kind":"history"}')->>'state'='forbidden','viewer cannot inspect private administrative history');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000206',pg_temp.role_input('ee620000-0000-4000-8000-000000000103','admin'))->>'state'='forbidden','viewer cannot regain administration');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000207',pg_temp.role_input('ee620000-0000-4000-8000-000000000103',null,'remove_member'),'ee620000-0000-4000-8000-000000000102')->>'state'='saved','current admin removes organization access');
select pg_temp.check_it((select org_id is null and role='viewer'from public.profiles where id='ee620000-0000-4000-8000-000000000103')and exists(select 1 from auth.users where id='ee620000-0000-4000-8000-000000000103'),'removal preserves the account and clears elevated role');
select pg_temp.check_it(pg_temp.read_team('{}','ee620000-0000-4000-8000-000000000103')->>'state'='forbidden','removed current session loses organization reads');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000208',pg_temp.role_input('ee620000-0000-4000-8000-000000000105'),'ee620000-0000-4000-8000-000000000102')->>'state'='not_found','another organization member is never falsely updated');
create function pg_temp.fail_action()returns trigger language plpgsql as $$begin if new.org_id='ee620000-0000-4000-8000-000000000001'then raise exception 'Fixture recording failure';end if;return new;end$$;
create trigger team_fixture_recording before insert on public.shared_action_events for each row execute function pg_temp.fail_action();
select pg_temp.throws($q$select pg_temp.decide('ee620000-0000-4000-8000-000000000209',pg_temp.role_input('ee620000-0000-4000-8000-000000000101','admin'),'ee620000-0000-4000-8000-000000000102')$q$,'failed semantic event rolls back membership change');
drop trigger team_fixture_recording on public.shared_action_events;
select pg_temp.check_it((select role='viewer'from public.profiles where id='ee620000-0000-4000-8000-000000000101')and not exists(select 1 from public.team_decisions where id='ee620000-0000-4000-8000-000000000209'),'failed recording leaves no changed role or partial private decision');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000210','{"operation":"cancel_unused","inputHash":"cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc","reason":"Stop unused team request"}','ee620000-0000-4000-8000-000000000102')->>'kind'='cancelled','unused team request can be cancelled');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000210',pg_temp.role_input('ee620000-0000-4000-8000-000000000101','admin'),'ee620000-0000-4000-8000-000000000102')->>'state'='decision_cancelled','late cancelled grant held');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000211',pg_temp.invite_input(),'ee620000-0000-4000-8000-000000000102',repeat('a',64))->>'state'='saved','reviewed invitation creates no automatic email');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000211',pg_temp.invite_input(),'ee620000-0000-4000-8000-000000000102',repeat('b',64))->>'state'='replayed','lost invitation result does not secretly replace the link');
select pg_temp.check_it((select token_hash=repeat('a',64)from public.team_invitations where id='ee620000-0000-4000-8000-000000000211'),'initial retained token digest stays exact');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000212',pg_temp.invite_input(),'ee620000-0000-4000-8000-000000000102',repeat('b',64))->>'state'='invitation_exists','duplicate pending invitation held');
select pg_temp.check_it(public.team_join_context('ee620000-0000-4000-8000-000000000105',repeat('a',64))->>'state'='recipient_mismatch','wrong verified account cannot use the link');
update auth.users set email_confirmed_at=null where id='ee620000-0000-4000-8000-000000000104';
select pg_temp.check_it(public.team_join_context('ee620000-0000-4000-8000-000000000104',repeat('a',64))->>'state'='verified_account_required','unverified account cannot accept invitation');
update auth.users set email_confirmed_at=clock_timestamp()where id='ee620000-0000-4000-8000-000000000104';
insert into st values('oldJoin',pg_temp.join_input('ee620000-0000-4000-8000-000000000104',repeat('a',64)));
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000213',pg_temp.invite_control('ee620000-0000-4000-8000-000000000211'),'ee620000-0000-4000-8000-000000000102',repeat('b',64))->>'state'='saved','lost secret can be replaced by explicit recorded rotation');
select pg_temp.check_it(public.team_join_context('ee620000-0000-4000-8000-000000000104',repeat('a',64))->>'state'='invitation_unavailable','old link no longer works after rotation');
select pg_temp.check_it(public.decide_team_join('ee620000-0000-4000-8000-000000000214','ee620000-0000-4000-8000-000000000104',repeat('b',64),(select v from st where k='oldJoin'))->>'state'='invitation_changed','old displayed grant cannot accept new link');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000215',pg_temp.role_input('ee620000-0000-4000-8000-000000000101','admin'),'ee620000-0000-4000-8000-000000000102')->>'state'='saved','reviewer can grant another administrator');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000216',pg_temp.role_input('ee620000-0000-4000-8000-000000000102','viewer'))->>'state'='saved','issuer authority can be removed');
select pg_temp.check_it(public.team_join_context('ee620000-0000-4000-8000-000000000104',repeat('b',64))->>'state'='issuer_unavailable','unaccepted grant requires current issuer authority');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000217',pg_temp.invite_control('ee620000-0000-4000-8000-000000000211'),'ee620000-0000-4000-8000-000000000101',repeat('c',64))->>'state'='saved','current admin can explicitly review and replace a held invitation');
insert into st values('join',pg_temp.join_input('ee620000-0000-4000-8000-000000000104',repeat('c',64)));
select pg_temp.check_it(public.decide_team_join('ee620000-0000-4000-8000-000000000218','ee620000-0000-4000-8000-000000000104',repeat('c',64),(select v from st where k='join'))->>'state'='saved','matching verified recipient explicitly joins once');
select pg_temp.check_it((select org_id='ee620000-0000-4000-8000-000000000001'and role='manager'from public.profiles where id='ee620000-0000-4000-8000-000000000104')and exists(select 1 from public.shared_action_events where id='ee620000-0000-4000-8000-000000000218'and actor_id='ee620000-0000-4000-8000-000000000104'and property_id is null),'acceptance membership and recipient-attributed action commit together');
select pg_temp.check_it(public.decide_team_join('ee620000-0000-4000-8000-000000000218','ee620000-0000-4000-8000-000000000104',null,(select v from st where k='join'))->>'state'='replayed','accepted result recovers even after the browser invitation cookie clears');
select pg_temp.check_it(public.read_team_join('ee620000-0000-4000-8000-000000000104',null,'ee620000-0000-4000-8000-000000000218')->'currentlyMember'='true','recipient saved-result recovery is scoped to the actual account');
select pg_temp.check_it(public.read_team_join('ee620000-0000-4000-8000-000000000105',null,'ee620000-0000-4000-8000-000000000218')->>'state'='not_found','another user cannot read an acceptance result');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000219',pg_temp.invite_input('team-103@fixture.invalid','viewer'),'ee620000-0000-4000-8000-000000000101',repeat('d',64))->>'state'='saved','removed member needs an explicit new invitation');
select pg_temp.check_it(public.decide_team_join('ee620000-0000-4000-8000-000000000220','ee620000-0000-4000-8000-000000000103',repeat('d',64),pg_temp.join_input('ee620000-0000-4000-8000-000000000103',repeat('d',64),'decline'))->>'kind'='invitation_declined','recipient can decline without gaining membership');
select pg_temp.check_it((select org_id is null from public.profiles where id='ee620000-0000-4000-8000-000000000103'),'decline preserves no access');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000221',pg_temp.invite_input('team-105@fixture.invalid','viewer'),'ee620000-0000-4000-8000-000000000101',repeat('e',64))->>'state'='saved','invitation itself never transfers an existing account');
select pg_temp.check_it(public.decide_team_join('ee620000-0000-4000-8000-000000000222','ee620000-0000-4000-8000-000000000105',repeat('e',64),pg_temp.join_input('ee620000-0000-4000-8000-000000000105',repeat('e',64)))->>'state'='other_organization','another organization account cannot be reassigned by accepting a link');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000223',pg_temp.invite_control('ee620000-0000-4000-8000-000000000221','revoke_invitation'))->>'state'='saved','explicit pending invitation revocation retained');
select pg_temp.check_it(public.team_join_context('ee620000-0000-4000-8000-000000000105',repeat('e',64))->>'state'='invitation_unavailable','revoked grant cannot be consumed');
select pg_temp.check_it(not has_table_privilege('authenticated','public.team_decisions','SELECT')and not has_function_privilege('authenticated','public.decide_team_access(uuid,uuid,uuid,jsonb,text)','EXECUTE'),'clients cannot bypass current scoped access');
select pg_temp.check_it(not exists(select 1 from public.shared_action_events where org_id='ee620000-0000-4000-8000-000000000001'and(training_eligible or request::text like'%fixture.invalid%'or request::text like'%token%')),'organization semantic history contains no recipient address or token and is not training eligible');
select pg_temp.check_it(public.report_team_invitation_copy('ee620000-0000-4000-8000-000000000224','ee620000-0000-4000-8000-000000000001','ee620000-0000-4000-8000-000000000101','ee620000-0000-4000-8000-000000000217','copied')->'linkStillCurrent'='false','late browser copy is retained honestly after acceptance');
select pg_temp.check_it(public.report_team_invitation_copy('ee620000-0000-4000-8000-000000000224','ee620000-0000-4000-8000-000000000001','ee620000-0000-4000-8000-000000000101','ee620000-0000-4000-8000-000000000217','copied')->>'state'='replayed','copy receipt recovers without another invitation');
select pg_temp.check_it(public.report_team_invitation_copy('ee620000-0000-4000-8000-000000000224','ee620000-0000-4000-8000-000000000001','ee620000-0000-4000-8000-000000000101','ee620000-0000-4000-8000-000000000217','failed')->>'state'='request_conflict','copy outcome cannot change under same identity');
select pg_temp.check_it(exists(select 1 from public.shared_action_events where id='ee620000-0000-4000-8000-000000000224' and evidence='browser_observed'and phase='observed'),'copy observation never claims server-confirmed delivery');
select pg_temp.check_it(public.report_team_invitation_copy('ee620000-0000-4000-8000-000000000225','ee620000-0000-4000-8000-000000000001','ee620000-0000-4000-8000-000000000101','ee620000-0000-4000-8000-000000000211','copied')->>'state'='not_found','copy report cannot use another operator preparation');
select pg_temp.check_it(public.cancel_team_join('ee620000-0000-4000-8000-000000000218','ee620000-0000-4000-8000-000000000104',null,repeat('c',64))->>'kind'='invitation_accepted','cancelling a completed join recovers acceptance without undo');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000226',pg_temp.invite_input('team-106@fixture.invalid','viewer'),'ee620000-0000-4000-8000-000000000101',repeat('f',64))->>'state'='saved','prepare unused recipient fixture');
insert into st values('unusedJoin',pg_temp.join_input('ee620000-0000-4000-8000-000000000106',repeat('f',64)));
select pg_temp.check_it(public.cancel_team_join('ee620000-0000-4000-8000-000000000227','ee620000-0000-4000-8000-000000000107',repeat('f',64),repeat('c',64))->>'state'='recipient_mismatch','other account cannot cancel recipient request');
select pg_temp.check_it(public.cancel_team_join('ee620000-0000-4000-8000-000000000227','ee620000-0000-4000-8000-000000000106',repeat('f',64),repeat('c',64))->'cancelled'='true','unused recipient request cancellation retained');
select pg_temp.check_it(public.cancel_team_join('ee620000-0000-4000-8000-000000000227','ee620000-0000-4000-8000-000000000106',null,repeat('c',64))->>'state'='replayed','cancelled recipient request recovers without secret');
select pg_temp.check_it(public.cancel_team_join('ee620000-0000-4000-8000-000000000227','ee620000-0000-4000-8000-000000000106',null,repeat('d',64))->>'state'='request_conflict','cancelled digest is immutable');
select pg_temp.check_it(public.decide_team_join('ee620000-0000-4000-8000-000000000227','ee620000-0000-4000-8000-000000000106',repeat('f',64),(select v from st where k='unusedJoin'))->>'state'='decision_cancelled','late cancelled recipient acceptance is fenced');
select pg_temp.check_it(public.team_join_context('ee620000-0000-4000-8000-000000000106',repeat('f',64))->>'state'='ready'and(select org_id is null from public.profiles where id='ee620000-0000-4000-8000-000000000106'),'cancelling unused request does not revoke invitation or grant access');
create trigger team_fixture_recording before insert on public.shared_action_events for each row execute function pg_temp.fail_action();
select pg_temp.throws($q$select public.decide_team_join('ee620000-0000-4000-8000-000000000228','ee620000-0000-4000-8000-000000000106',repeat('f',64),(select v from st where k='unusedJoin'))$q$,'acceptance recording failure rolls back grant and invitation consumption');
drop trigger team_fixture_recording on public.shared_action_events;
select pg_temp.check_it((select org_id is null from public.profiles where id='ee620000-0000-4000-8000-000000000106')and(select status='pending'from public.team_invitations where id='ee620000-0000-4000-8000-000000000226')and not exists(select 1 from public.team_decisions where id='ee620000-0000-4000-8000-000000000228'),'acceptance recording failure leaves no partial effect');
