select set_config('p11.team_scope','ee620000-0000-4000-8000-000000000001',true);update public.team_invitations set expires_at=clock_timestamp()-interval'1 second'where id='ee620000-0000-4000-8000-000000000226';select set_config('p11.team_scope','',true);
