select pg_temp.check_it(public.cancel_team_join('ee620000-0000-4000-8000-000000000229','ee620000-0000-4000-8000-000000000106',repeat('f',64),repeat('e',64))->>'state'='saved','expired invitation can still close an unused request safely');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000230',pg_temp.invite_control('ee620000-0000-4000-8000-000000000226'),'ee620000-0000-4000-8000-000000000101',repeat('9',64))->>'state'='saved','explicit administrator review replaces expired link');
select pg_temp.check_it(public.report_team_invitation_copy('ee620000-0000-4000-8000-000000000231','ee620000-0000-4000-8000-000000000001','ee620000-0000-4000-8000-000000000101','ee620000-0000-4000-8000-000000000230','failed')->'linkStillCurrent'='true','clipboard failure is retained without changing invitation');
select set_config('p11.team_scope','ee620000-0000-4000-8000-000000000001',true);
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at)select ('ee620000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','team-'||n||'@fixture.invalid',clock_timestamp(),clock_timestamp(),clock_timestamp()from generate_series(1001,2025)n;
insert into public.profiles(id,org_id,role,full_name)select ('ee620000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'ee620000-0000-4000-8000-000000000001','viewer','Paged team fixture '||n from generate_series(1001,2025)n on conflict(id)do update set org_id=excluded.org_id,role=excluded.role,full_name=excluded.full_name;
select set_config('p11.team_scope','',true);
select pg_temp.check_it(pg_temp.read_team()->>'total'='1028','native roster includes every member beyond one thousand');
select pg_temp.check_it(jsonb_array_length(pg_temp.read_team('{"offset":1020}')->'items')=8 and pg_temp.read_team('{"offset":1020}')->'nextOffset'='null','last roster page is reachable without client row cap');
