set local role service_role;
select pg_temp.check_it(pg_temp.read_team()->>'total'='1028','application service can read complete safe roster');
select pg_temp.check_it(pg_temp.decide('ee620000-0000-4000-8000-000000000232',pg_temp.role_input('ee620000-0000-4000-8000-000000000104','viewer'))->>'state'='saved','application service can record exact role changes');
